#!/usr/bin/env bash
# Cowfee Raid Tools test suite: Lua harnesses run with fengari under Node (no Lua runtime needed).
#   bash Tests/run_all.sh [addon folder]   defaults to the checkout this script is in
# First run: cd Tests && npm install. Prints each group; ends with a summary line and exits 1 on any failure.
W="${1:-$(cd "$(dirname "$0")/.." && (pwd -W 2>/dev/null || pwd))}"
cd "$(dirname "$0")"
for t in "store Timeline/Data.lua" "record Timeline/Data.lua" "journal Timeline/Journal.lua" "reference Timeline/Database.lua Timeline/Reference.lua" "probe Dev/TimelineProbe.lua" "lanes Timeline/Data.lua Timeline/Database.lua Timeline/Reference.lua Timeline/Lanes.lua" "view Timeline/Data.lua Timeline/Database.lua Timeline/Reference.lua Timeline/Lanes.lua Timeline/View.lua" "page Timeline/Data.lua Timeline/Database.lua Timeline/Reference.lua Timeline/Lanes.lua Timeline/ReferencePage.lua Timeline/SettingsTab.lua Timeline/Page.lua Timeline/Journal.lua"; do
  set -- $t; n=$1; shift; case $n in reference|view|page) set -- "$@" Bosses/Registry.lua Seasons/Midnight-S1/Season.lua Seasons/Midnight-S1/NekzaliTheSoulcoiler.lua;; esac; [ "$n" = page ] && set -- "$@" Timeline/ReviewTab.lua Timeline/Rehearsal.lua Timeline/RehearsalWindow.lua Slash.lua; args=""; for f in "$@"; do args="$args \"$W/$f\""; done
  echo "== $n"; eval node run_timeline_$n.js $args 2>&1 | tail -${TAIL:-40}; echo "exit ${PIPESTATUS[0]}"
done
echo "== profiles"; node run_profiles.js "$W/Profiles.lua" 2>&1 | tail -30; echo "exit ${PIPESTATUS[0]}"
echo "== settings"; node run_settings.js "$W" 2>&1 | tail -15; echo "exit ${PIPESTATUS[0]}"
WA="$W"
echo "== alerts rules"; node run_alerts_rules.js "$WA/Alerts/Rules.lua" 2>&1 | tail -12; echo "exit ${PIPESTATUS[0]}"
echo "== alerts engine"; node run_alerts_engine.js "$WA/Alerts/Rules.lua" "$WA/Alerts/Engine.lua" 2>&1 | tail -12; echo "exit ${PIPESTATUS[0]}"
echo "== alerts notes"; node run_alerts_notes.js old_Engine.lua old_Alert.lua "$WA/Alerts/Rules.lua" "$WA/Alerts/Engine.lua" "$WA/Notes/Parse.lua" "$WA/Notes/Data.lua" "$WA/Notes/Engine.lua" "$WA/Notes/Window.lua" "$WA/Notes/Alert.lua" "$WA/Alerts/Speech.lua" "$WA/Sound/Engine.lua" 2>&1 | tail -10; echo "exit ${PIPESTATUS[0]}"
echo "== alerts speech"; node run_alerts_speech.js "$WA/Alerts/Rules.lua" "$WA/Alerts/Engine.lua" "$WA/Sound/Engine.lua" "$WA/Alerts/Speech.lua" 2>&1 | tail -10; echo "exit ${PIPESTATUS[0]}"
echo "== alerts reminders"; node run_alerts_reminders.js "$WA/Timeline/Data.lua" "$WA/Timeline/Database.lua" "$WA/Timeline/Reference.lua" "$WA/Timeline/Lanes.lua" "$WA/Alerts/Rules.lua" "$WA/Alerts/Engine.lua" "$WA/Alerts/Reminders.lua" "$WA/Bosses/Registry.lua" "$WA/Seasons/Midnight-S1/Season.lua" "$WA/Seasons/Midnight-S1/NekzaliTheSoulcoiler.lua" 2>&1  | tail -12; echo "exit ${PIPESTATUS[0]}"
echo "== alerts phases"; node run_alerts_phases.js "$WA/Alerts/Rules.lua" "$WA/Alerts/Engine.lua" "$WA/Alerts/PhaseDatabase.lua" "$WA/Alerts/Phases.lua" 2>&1 | tail -12; echo "exit ${PIPESTATUS[0]}"
echo "== alerts bars"; node run_alerts_bars.js "$WA/Alerts/Rules.lua" "$WA/Alerts/Engine.lua" "$WA/Alerts/Areas.lua" "$WA/Alerts/Bars.lua" 2>&1 | tail -14; echo "exit ${PIPESTATUS[0]}"
echo "== alerts areas"; node run_alerts_areas.js "$WA/Alerts/Rules.lua" "$WA/Alerts/Engine.lua" "$WA/Alerts/Areas.lua" "$WA/Alerts/Texts.lua" 2>&1 | tail -14; echo "exit ${PIPESTATUS[0]}"
echo "== alerts icons"; node run_alerts_icons.js "$WA/Alerts/Rules.lua" "$WA/Alerts/Engine.lua" "$WA/Alerts/Areas.lua" "$WA/Alerts/Icons.lua" 2>&1 | tail -10; echo "exit ${PIPESTATUS[0]}"
echo "== alerts circles"; node run_alerts_circles.js "$WA/Alerts/Rules.lua" "$WA/Alerts/Engine.lua" "$WA/Alerts/Areas.lua" "$WA/Alerts/Circles.lua" "$WA/UI/Controls.lua" 2>&1 | tail -10; echo "exit ${PIPESTATUS[0]}"
echo "== alerts editor"; node run_alerts_editor.js "$WA/UI/Panel.lua" "$WA/Timeline/Data.lua" "$WA/Timeline/Database.lua" "$WA/Timeline/Reference.lua" "$WA/Timeline/Lanes.lua" "$WA/Alerts/Rules.lua" "$WA/Alerts/Engine.lua" "$WA/Sound/Engine.lua" "$WA/Alerts/Speech.lua" "$WA/Notes/Parse.lua" "$WA/Notes/Data.lua" "$WA/Notes/Engine.lua" "$WA/Alerts/Reminders.lua" "$WA/Alerts/Draft.lua" "$WA/Alerts/SpellLookup.lua" "$WA/Alerts/Editor.lua" "$WA/UI/Controls.lua" 2>&1 | tail -22; echo "exit ${PIPESTATUS[0]}"
