echo "== alerts tabs"; node run_alerts_tabs.js "$WA/Timeline/Data.lua" "$WA/Timeline/Database.lua" "$WA/Timeline/Reference.lua" "$WA/Timeline/Lanes.lua" "$WA/Alerts/Rules.lua" "$WA/Alerts/Engine.lua" "$WA/Alerts/Reminders.lua" "$WA/Alerts/PhaseDatabase.lua" "$WA/Alerts/Phases.lua" "$WA/Sound/Engine.lua" "$WA/Alerts/Draft.lua" "$WA/Alerts/SpellLookup.lua" "$WA/Notes/Reminders.lua" "$WA/Notes/Phases.lua" "$WA/Notes/Page.lua" 2>&1 | tail -20; echo "exit ${PIPESTATUS[0]}"
