echo "== alerts timeline"; node run_alerts_timeline.js "$WA/Timeline/Data.lua" "$WA/Timeline/Database.lua" "$WA/Timeline/Reference.lua" "$WA/Timeline/Lanes.lua" "$WA/Timeline/View.lua" "$WA/Alerts/Rules.lua" "$WA/Alerts/Engine.lua" "$WA/Alerts/Reminders.lua" "$WA/Slash.lua" 2>&1 | tail -14; echo "exit ${PIPESTATUS[0]}"
echo "== alerts fields"; node run_alerts_fields.js "$WA/Timeline/Data.lua" "$WA/Timeline/Database.lua" "$WA/Timeline/Reference.lua" "$WA/Timeline/Lanes.lua" "$WA/Alerts/Rules.lua" "$WA/Alerts/Engine.lua" "$WA/Alerts/Reminders.lua" "$WA/Sound/Engine.lua" "$WA/Alerts/Speech.lua" 2>&1 | tail -14; echo "exit ${PIPESTATUS[0]}"
